// Generated by OrchestKit Claude Plugin
// Created: 2026-07-17

// Search analytics beacons. Fire-and-forget logs through the EXISTING
// first-party analytics proxy at /api/analytics (same envelope as
// components/web-vitals-reporter.tsx — no new vendor, no hand-rolled HMAC).
//
// CONTRACT: /api/analytics is the system of record, PostHog is a mirror. Every
// event in this file goes through `send()` so all three rules hold by
// construction rather than by convention:
//   1. the first-party sink is written FIRST and independently,
//   2. the mirror can never fail the caller (mirrorToPostHog swallows), and
//   3. one event name string reaches both sinks, so they cannot drift.
// Adding a copy-pasted sender here for a new event breaks rule 3. Extend
// `send()` instead.
//
// Fail-open everywhere: a beacon must never throw or block the dialog.

import { mirrorToPostHog } from "@/lib/posthog-mirror";
import { truncateQuery } from "@/lib/search-relevance";

const PROJECT_ID = "orchestkit";
const ENDPOINT = "/api/analytics";

type EventProps = Record<string, string | number | boolean>;

/**
 * The single dual-send chokepoint for search events.
 *
 * `mirrorProps` defaults to the first-party props. Pass a narrower object when
 * a property is safe for the authoritative sink but not for a vendor. Raw
 * query text is the case that matters here: a docs search box is an unbounded
 * input and users paste tokens, hostnames and email addresses into it, and
 * truncateQuery is a length cap, NOT a redactor.
 */
function send(name: string, props: EventProps, mirrorProps: EventProps = props) {
	try {
		if (process.env.NODE_ENV === "development") return;
		const body = JSON.stringify({
			project_id: PROJECT_ID,
			events: [
				{
					name,
					path: window.location.pathname,
					referrer: "",
					properties: props,
				},
			],
		});
		// sendBeacon survives the page unload that a result click starts. The
		// keepalive fetch is the fallback for browsers without it, for the same
		// reason: a plain fetch would be cancelled mid-navigation.
		if (
			typeof navigator !== "undefined" &&
			typeof navigator.sendBeacon === "function"
		) {
			navigator.sendBeacon(
				ENDPOINT,
				new Blob([body], { type: "application/json" }),
			);
		} else {
			void fetch(ENDPOINT, {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body,
				keepalive: true,
			}).catch(() => {});
		}
		// Mirror AFTER the first-party send, so PostHog can never be the reason
		// the authoritative sink misses an event.
		mirrorToPostHog(name, mirrorProps);
	} catch {
		// fail-open
	}
}

/** Report a query that returned zero results. Safe to call anywhere client-side. */
export function reportZeroResultQuery(query: string): void {
	const truncated = truncateQuery(query);
	if (!truncated) return;
	// The literal text IS the signal for a zero-result query (it is the content-gap
	// backlog) and the volume is tiny, so this one event mirrors the query. That is
	// a deliberate carry-over of the shipped behaviour, not the default below.
	send("search:zero-results", { query: truncated });
}

/**
 * Report a settled search. Callers MUST debounce: this is once per search, not
 * once per keystroke (fumadocs' own delay is only 100ms).
 */
export function reportSearchPerformed(input: {
	query: string;
	resultCount: number;
	tag: string;
	/**
	 * Search execution time in milliseconds. Client-side `performance.now()`
	 * measured from debounce-settle to results-arrived (see
	 * components/search-dialog.tsx) — NOT the server's own Server-Timing
	 * value. fumadocs' `useDocsSearch({ type: "fetch" })` wraps `fetch()`
	 * internally (fumadocs-core/dist/search/client/fetch.js) and only
	 * returns the parsed JSON body, never the `Response`, so the
	 * `Server-Timing: search;dur=<ms>` header app/api/search/route.ts emits
	 * is not reachable from this call site without forking fumadocs' client.
	 * Omitted when unavailable (e.g. no search has completed yet).
	 */
	durationMs?: number;
}): void {
	const truncated = truncateQuery(input.query);
	if (!truncated) return;
	const props = {
		query: truncated,
		result_count: input.resultCount,
		tag: input.tag,
		...(input.durationMs !== undefined ? { duration_ms: input.durationMs } : {}),
	};
	// This is the highest-volume search event, so the query stays first-party
	// only; query_length keeps the mirror useful without exporting free text.
	send("search:performed", props, {
		query_length: truncated.length,
		result_count: input.resultCount,
		tag: input.tag,
		...(input.durationMs !== undefined ? { duration_ms: input.durationMs } : {}),
	});
}

/**
 * Report which result a user picked. `position` is the ZERO-BASED index of the
 * item in the list AS RENDERED, which is the whole point of the event: it is
 * how a ranking change is graded against real behaviour.
 */
export function reportSearchResultClicked(input: {
	query: string;
	url: string;
	position: number;
	resultType: string;
	tag: string;
}): void {
	const truncated = truncateQuery(input.query);
	const props = {
		query: truncated,
		url: input.url,
		position: input.position,
		result_type: input.resultType,
		tag: input.tag,
	};
	send("search:result-clicked", props, {
		query_length: truncated.length,
		url: input.url,
		position: input.position,
		result_type: input.resultType,
		tag: input.tag,
	});
}
